head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.__checkErrLog = function() {
    var err = WebSquare.logger.getLog();
    return err.indexOf("scwin.expTotal is not a function") == -1;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
